-- MT2009_PLUS_ZODIAC_V1: Swiatynia Zodiaku - Autor: Digi Rasta (nowy-system 0.35.0, 96_zodiak.sql, from WLsj24's
-- "ZodiacTemple" and the official 2019 data; server-patches/zodiak/README.md). Every start (apply.sh), idempotent:
-- INSERT IGNORE / ADD COLUMN IF NOT EXISTS - nothing of ours is overwritten (every vnum, id and the shop 41 checked free
-- on 8 October 2026). Left out of the package's file: the delete of its own older Zodiac families (95_wiki_nowe.sql,
-- refine_proto 22301-22309), which our world never had.
SET NAMES utf8mb4;

-- ---- gracz: Kule Animy i limity zakupu u Kupca Zodiaku (decyzja 08.10: jak w paczce)
ALTER TABLE player.player ADD COLUMN IF NOT EXISTS `bead` int(11) NOT NULL DEFAULT 0 COMMENT 'ENABLE_12ZI';
ALTER TABLE player.player_deleted ADD COLUMN IF NOT EXISTS `bead` int(11) NOT NULL DEFAULT 0 COMMENT 'ENABLE_12ZI';
CREATE TABLE IF NOT EXISTS player.zodiac_npc (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `owner_id` int(10) unsigned NOT NULL,
  `item_vnum` int(10) unsigned NOT NULL,
  `count` int(10) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `owner_item` (`owner_id`,`item_vnum`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;
CREATE TABLE IF NOT EXISTS player.zodiac_npc_sold (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `owner_id` int(10) unsigned NOT NULL,
  `item_vnum` int(10) unsigned NOT NULL,
  `count` int(10) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `owner_item` (`owner_id`,`item_vnum`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


-- ---- przedmioty (166; Korony 45314-45317 sa u moda)

-- ---- receptury ulepszania z paczki pod nowymi id (361-369 -> 22401-22409 pancerze, 440-448 -> 22410-22418 bronie; stare id zajmuje mod)
-- MT2009_PLUS_ZODIAC_ITEMS_V1 (9 October, the PL wiki's Zbroja/Miecz Zodiaku): the second material of +1..+5 is Ciezkie
-- Pasy (95603) for the armours and Stabilne Sznury (95601) for the weapons - the package's 30611 / 30612 are no items of
-- ours (MT2009_PLUS_NS_WIKI_ITEMS_V1 has them under 95601-95603); +6..+8 Dwutlenek Tytanu, Agat, Kamien Ksiezycowy (30616-30618).
ON DUPLICATE KEY UPDATE vnum0 = VALUES(vnum0), count0 = VALUES(count0), vnum1 = VALUES(vnum1), count1 = VALUES(count1), cost = VALUES(cost), prob = VALUES(prob);

